_CLUSTER_A = [0, 2, 100, 105, 106, 107, 108, 120, 121, 122, 124, 125]
_CLUSTER_B = [1, 3, 4, 5, 6, 7, 8, 10, 11, 12, 109, 126, 127, 128]
_CLUSTER_C = [101, 103, 104, 112, 113, 116, 118, 119]

def _get_cluster(r):
    if r in _CLUSTER_A: return _CLUSTER_A
    if r in _CLUSTER_B: return _CLUSTER_B
    if r in _CLUSTER_C: return _CLUSTER_C
    return [r]

