def _score_route_demand(r, unlocked_shops, prices=None):
    s = _ROUTE_SELL_PROFILES.get(r, {})
    score = 0
    for shop in unlocked_shops:
        mults = _SHOP_DEMANDS.get(shop, {})
        for item, m in mults.items():
            sold = s.get(item, 0)
            px = (prices or {}).get(item, 25)
            score += sold * px * m
    return score
